// 数据清理：过滤掉source为空的历史数据
const existingRecords = $input.first().json;

if (existingRecords && existingRecords.data && existingRecords.data.items) {
  const originalCount = existingRecords.data.items.length;
  existingRecords.data.items = existingRecords.data.items.filter(record => {
    const fields = record.fields;
    return fields.source && fields.source.trim() !== '';
  });

  console.log(`数据清理：从 ${originalCount} 条记录中过滤出 ${existingRecords.data.items.length} 条有效记录`);
}

// 添加延迟函数
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

// 获取RSS文章数据（从Collect RSS Articles节点）
const rssArticles = $('Collect RSS Articles').all();

console.log('=== 优化后的去重调试 ===');
console.log('RSS文章数量:', rssArticles.length);
console.log('飞书记录数量:', existingRecords?.data?.items?.length || 0);

// 检查是否有错误
if (existingRecords && existingRecords.errorMessage) {
  console.log('检测到错误:', existingRecords.errorMessage);

  // 如果是频率限制错误，优化延迟时间
  if (existingRecords.errorMessage.includes('request trigger frequency limit')) {
    console.log('API频率限制，等待10秒后重试...');
    await delay(10000);

    return [];
  }

  return [];
}

// 如果没有现有记录，直接返回所有RSS文章
if (!existingRecords || !existingRecords.data || !existingRecords.data.items) {
  console.log('没有找到现有记录，返回所有RSS文章');
  return rssArticles;
}

// 创建现有数据的索引（多重去重）
const existingUrls = new Set();
const existingTitles = new Set();
const existingSummaries = new Set();

existingRecords.data.items.forEach(record => {
  const fields = record.fields;

  // URL去重
  if (fields.url && fields.url.link) {
    const url = fields.url.link.toLowerCase().trim();
    if (url) {
      existingUrls.add(url);
    }
  }

  // 标题去重
  if (fields.title) {
    const title = fields.title.toLowerCase().trim();
    if (title) {
      existingTitles.add(title);
    }
  }

  // 摘要去重（用于检测内容重复）
  if (fields.summary) {
    const summary = fields.summary.toLowerCase().trim();
    if (summary && summary.length > 20) { // 只处理有意义的摘要
      existingSummaries.add(summary);
    }
  }
});

console.log(`飞书表格中现有URL数量: ${existingUrls.size}`);
console.log(`飞书表格中现有标题数量: ${existingTitles.size}`);
console.log(`飞书表格中现有摘要数量: ${existingSummaries.size}`);

// 修改前（近两周）
// const twoWeeksAgo = new Date(Date.now() - 14 * 24 * 60 * 60 * 1000);
// console.log('两周前的时间:', twoWeeksAgo.toISOString());

// 时间过滤：只处理2天内的文章
const twoDaysAgo = new Date(Date.now() - 2 * 24 * 60 * 60 * 1000);
console.log('两天前的时间:', twoDaysAgo.toISOString());

// 简单的相似度计算函数
function calculateSimilarity(str1, str2) {
  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;

  if (longer.length === 0) return 1.0;

  const editDistance = levenshteinDistance(longer, shorter);
  return (longer.length - editDistance) / longer.length;
}

// 计算编辑距离
function levenshteinDistance(str1, str2) {
  const matrix = [];

  for (let i = 0; i <= str2.length; i++) {
    matrix[i] = [i];
  }

  for (let j = 0; j <= str1.length; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i <= str2.length; i++) {
    for (let j = 1; j <= str1.length; j++) {
      if (str2.charAt(i - 1) === str1.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j] + 1
        );
      }
    }
  }

  return matrix[str2.length][str1.length];
}

// 过滤掉已存在的文章 + 时间过滤 + 智能去重
const newArticles = [];
let duplicateCount = 0;
let timeFilteredCount = 0;
let urlDuplicateCount = 0;
let titleDuplicateCount = 0;
let contentSimilarCount = 0;

rssArticles.forEach(article => {
  if (!article || !article.json || !article.json.link) {
    console.log('跳过无效文章:', article);
    return;
  }

  // 时间过滤
  try {
    const articleDate = new Date(article.json.pubDate);
    if (isNaN(articleDate.getTime())) {
      console.log('无效日期格式:', article.json.pubDate);
      return;
    }

    if (articleDate < twoDaysAgo) {
      timeFilteredCount++;
      console.log('时间过滤掉:', article.json.title, articleDate.toISOString());
      return;
    }
  } catch (error) {
    console.log('日期解析错误:', error, '原始日期:', article.json.pubDate);
    return;
  }

  // 多重去重检查
  const articleUrl = article.json.link.toLowerCase().trim();
  const articleTitle = article.json.title ? article.json.title.toLowerCase().trim() : '';
  const articleSummary = article.json.description ? article.json.description.toLowerCase().trim() : '';

  let isDuplicate = false;
  let duplicateReason = '';

  // 1. URL去重
  if (existingUrls.has(articleUrl)) {
    isDuplicate = true;
    duplicateReason = 'URL重复';
    urlDuplicateCount++;
  }

  // 2. 标题去重
  if (!isDuplicate && articleTitle && existingTitles.has(articleTitle)) {
    isDuplicate = true;
    duplicateReason = '标题重复';
    titleDuplicateCount++;
  }

  // 3. 摘要相似度去重
  if (!isDuplicate && articleSummary && articleSummary.length > 20) {
    for (const existingSummary of existingSummaries) {
      const similarity = calculateSimilarity(articleSummary, existingSummary);
      if (similarity > 0.8) { // 80%相似度阈值
        isDuplicate = true;
        duplicateReason = `内容相似 (${Math.round(similarity * 100)}%)`;
        contentSimilarCount++;
        break;
      }
    }
  }

  if (!isDuplicate) {
    newArticles.push(article);
    console.log(`✅ 新文章: ${article.json.title}`);
  } else {
    duplicateCount++;
    console.log(`❌ 重复文章: ${article.json.title} - 原因: ${duplicateReason}`);
  }
});

// 统计信息
console.log(`\n=== 去重统计 ===`);
console.log(`RSS文章总数: ${rssArticles.length}`);
console.log(`时间过滤掉: ${timeFilteredCount}`);
console.log(`URL重复: ${urlDuplicateCount}`);
console.log(`标题重复: ${titleDuplicateCount}`);
console.log(`内容相似: ${contentSimilarCount}`);
console.log(`总重复数量: ${duplicateCount}`);
console.log(`新文章数量: ${newArticles.length}`);

if (newArticles.length === 0) {
  console.log('没有新文章需要处理');
  return [];
}

// 返回原始格式的文章数据，让AI Analysis节点能正确接收
return newArticles;

// 获取配置和token
const config = $('Configuration').item.json;
const tokenData = $('Get Feishu Token').item.json;
const token = tokenData.tenant_access_token;

if (!token) {
  throw new Error('无法获取飞书访问令牌');
}

// 收集所有RSS数据
const allArticles = [];
const inputs = $input.all();

console.log('=== RSS收集调试信息 ===');
console.log('输入节点数量:', inputs.length);

// 根据RSS源URL确定来源的映射
const rssSourceMapping = {
  'https://plink.anyfeeder.com/weixin/AI_era': '新智元',
  'https://rsshub.app/aibase/news': 'AIBase',
  'https://plink.anyfeeder.com/weixin/qqtech': '腾讯科技',
  'https://www.qbitai.com/feed': '量子位',
  'https://36kr.com/feed': '36氪',
  'https://www.jiqizhixin.com/rss': '机器之心',
  'http://www.geekpark.net/rss': '极客公园'
};

// 处理RSS Feed Read节点的数据
for (let i = 0; i < inputs.length; i++) {
  console.log(`处理RSS节点 ${i}...`);

  if (inputs[i].json) {
    let sourceName = '未知来源';

    // 方法1：从RSS源URL中确定来源
    const rssSourceUrl = inputs[i].json?.rssSourceUrl || inputs[i].json?.sourceUrl || '';
    console.log(`RSS节点 ${i} rssSourceUrl: ${rssSourceUrl}`);

    for (const [urlPattern, source] of Object.entries(rssSourceMapping)) {
      if (rssSourceUrl.includes(urlPattern) || rssSourceUrl === urlPattern) {
        sourceName = source;
        console.log(`通过rssSourceUrl匹配到来源: ${source} (模式: ${urlPattern})`);
        break;
      }
    }

    // 方法2：从文章链接中确定来源
    if (sourceName === '未知来源') {
      const articleUrl = inputs[i].json?.link || inputs[i].json?.url || '';
      console.log(`RSS节点 ${i} 文章链接: ${articleUrl}`);

      if (articleUrl.includes('weixin.sogou.com') && articleUrl.includes('AI_era')) sourceName = '新智元';
      else if (articleUrl.includes('aibase.com')) sourceName = 'AIBase';
      else if (articleUrl.includes('weixin.sogou.com') && articleUrl.includes('qqtech')) sourceName = '腾讯科技';
      else if (articleUrl.includes('qbitai.com')) sourceName = '量子位';
      else if (articleUrl.includes('36kr.com')) sourceName = '36氪';
      else if (articleUrl.includes('jiqizhixin.com')) sourceName = '机器之心';
      else if (articleUrl.includes('geekpark.net')) sourceName = '极客公园';

      if (sourceName !== '未知来源') {
        console.log(`通过文章链接匹配到来源: ${sourceName}`);
      }
    }

    // 方法3：从feedTitle中确定来源
    if (sourceName === '未知来源') {
      const feedTitle = inputs[i].json?.feedTitle || inputs[i].json?.title || '';
      console.log(`RSS节点 ${i} feedTitle: ${feedTitle}`);

      if (feedTitle.includes('AI_era') || feedTitle.includes('新智元')) sourceName = '新智元';
      else if (feedTitle.includes('aibase') || feedTitle.includes('AIBase')) sourceName = 'AIBase';
      else if (feedTitle.includes('qqtech') || feedTitle.includes('腾讯科技')) sourceName = '腾讯科技';
      else if (feedTitle.includes('qbitai') || feedTitle.includes('量子位')) sourceName = '量子位';
      else if (feedTitle.includes('36kr') || feedTitle.includes('36氪')) sourceName = '36氪';
      else if (feedTitle.includes('jiqizhixin') || feedTitle.includes('机器之心')) sourceName = '机器之心';
      else if (feedTitle.includes('geekpark') || feedTitle.includes('极客公园')) sourceName = '极客公园';

      if (sourceName !== '未知来源') {
        console.log(`通过feedTitle匹配到来源: ${sourceName}`);
      }
    }

    // 方法4：从creator字段中确定来源（作为备用）
    if (sourceName === '未知来源') {
      const creator = inputs[i].json?.creator || '';
      console.log(`RSS节点 ${i} creator: ${creator}`);

      if (creator.includes('AI base') || creator.includes('AIBase')) sourceName = 'AIBase';
      else if (creator.includes('明敏')) sourceName = '量子位';

      if (sourceName !== '未知来源') {
        console.log(`通过creator匹配到来源: ${sourceName}`);
      }
    }

    // 方法5：根据输入顺序确定来源（最后备用）
    if (sourceName === '未知来源') {
      const predefinedSources = ['新智元', 'AIBase', '腾讯科技', '量子位', '量子位', '36氪', '机器之心', '极客公园'];
      const sourceIndex = i;
      if (sourceIndex >= 0 && sourceIndex < predefinedSources.length) {
        sourceName = predefinedSources[sourceIndex];
        console.log(`通过输入顺序匹配到来源: ${sourceName} (索引: ${sourceIndex})`);
      }
    }

    console.log(`RSS节点 ${i} 最终来源: ${sourceName}`);
    console.log(`RSS节点 ${i} 完整数据:`, JSON.stringify(inputs[i].json, null, 2));

    // RSS Feed Read节点会直接返回解析好的数据
    const article = inputs[i].json;

    // 处理时间格式
    let pubDate = article.pubDate || article.published || new Date().toISOString();

    // 如果是Unix时间戳（数字），转换为ISO字符串
    if (typeof pubDate === 'number') {
      pubDate = new Date(pubDate * 1000).toISOString();
    } else if (typeof pubDate === 'string') {
      // 尝试解析各种日期格式
      const date = new Date(pubDate);
      if (!isNaN(date.getTime())) {
        pubDate = date.toISOString();
      } else {
        pubDate = new Date().toISOString();
      }
    }

    const newArticle = {
      title: article.title || article.name || '',
      description: article.description || article.content || article.summary || '',
      link: article.link || article.url || '',
      pubDate: pubDate,
      source: sourceName,
      guid: article.guid || article.id || '',
      feedTitle: article.feedTitle || sourceName,
      creator: article.creator || '',
      rssSourceUrl: article.rssSourceUrl || ''
    };

    console.log(`添加RSS文章:`, newArticle);
    allArticles.push(newArticle);
  }
}

// 去重处理（基于标题和链接）
const uniqueArticles = [];
const seenTitles = new Set();
const seenLinks = new Set();

allArticles.forEach(article => {
  const titleKey = article.title.toLowerCase().trim();
  const linkKey = article.link.toLowerCase().trim();

  if (!seenTitles.has(titleKey) && !seenLinks.has(linkKey)) {
    seenTitles.add(titleKey);
    seenLinks.add(linkKey);
    uniqueArticles.push(article);
  } else {
    console.log('跳过重复RSS文章:', article.title);
  }
});

console.log(`收集到 ${uniqueArticles.length} 篇RSS文章（去重后）`);

// 为每篇文章添加配置信息
return uniqueArticles.map(article => ({
  ...article,
  _token: token,
  _config: config,
  created_at: new Date().toISOString(),
  status: '待筛选',
  article_type: 'rss'
}));

// 在 Catch Error 节点的 JavaScript 代码中
const error = $input.first().json;

console.log('Query Existing Records 节点出错:', error);

// 检查是否是频率限制错误
if (error.errorMessage && error.errorMessage.includes('request trigger frequency limit')) {
  console.log('检测到API频率限制，等待重试...');

  // 等待一段时间后重试
  await new Promise(resolve => setTimeout(resolve, 10000)); // 等待10秒

  // 可以在这里添加重试逻辑或发送通知
  return [{
    json: {
      error_type: 'rate_limit',
      message: 'API频率限制，已等待重试',
      retry_after: 10
    }
  }];
}

// 其他错误处理
return [{
  json: {
    error_type: 'other',
    message: error.errorMessage || '未知错误',
    original_error: error
  }
}];
